import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Box3, Vector3 } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { scenePosition, sceneRotation, sceneScale, textContent, visual } = config;

  const group = new Group();
  group.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  group.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
  group.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // --- Text layer ---
  const textNode = ctx.fontAtlas.createText({
    text: textContent?.headline || 'Pricing',
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 0.62, // hero scene unit height
    align: 'center',
    verticalAlign: 'middle',
    color: visual?.colors?.ink || '#16161d'
  });

  // Compute text bounding box for background sizing
  const textBounds = new Box3().setFromObject(textNode);
  const textSize = textBounds.getSize(new Vector3());
  const padding = 0.25; // spacing rhythm base unit

  const planeWidth = textSize.x + 2 * padding;
  const planeHeight = textSize.y + 2 * padding;

  // --- Background layer ---
  const bgTexture = ctx.textureLoader.load(
    config.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png'
  );
  bgTexture.needsUpdate = true;

  const bgMat = new MeshBasicNodeMaterial({ map: bgTexture });
  const bgGeo = new PlaneGeometry(planeWidth, planeHeight);
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.01); // slight offset behind text

  // --- Assemble ---
  group.add(bgMesh);
  group.add(textNode);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    bgGeo.dispose();
    bgMat.dispose();
    bgTexture.dispose();
    if (textNode.userData?.cleanup) {
      textNode.userData.cleanup();
    }
    // No GSAP timelines to kill
  };

  // No event handlers (no interactions)
  group.userData.handlers = {};

  return group;
}
